<?php
namespace App\Models;
use App\Enums\InstallationStatus; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany,HasOne}; use Illuminate\Support\Str;
class IkontrolInstance extends Model { protected $fillable=['uuid','client_id','ikontrol_version_id','name','slug','folder_name','absolute_path','domain','url','db_host','db_port','db_name','app_version','installed_version','installed_at','schema_version','schema_status','schema_checked_at','schema_error','installation_status','active','last_connection_at','last_connection_status','last_connection_error']; protected static function booted(): void { static::creating(fn($m)=>$m->uuid ??= (string) Str::uuid()); } protected function casts(): array { return ['installation_status'=>InstallationStatus::class,'active'=>'boolean','last_connection_at'=>'datetime','installed_at'=>'datetime','schema_checked_at'=>'datetime']; } public function client(): BelongsTo { return $this->belongsTo(Client::class); } public function version(): BelongsTo { return $this->belongsTo(IkontrolVersion::class,'ikontrol_version_id'); } public function installationLogs(): HasMany { return $this->hasMany(InstanceInstallationLog::class,'instance_id')->latest('id'); } public function inspectionSnapshots(): HasMany { return $this->hasMany(InstanceInspectionSnapshot::class,'instance_id')->latest('inspected_at'); } public function latestInspection(): HasOne { return $this->hasOne(InstanceInspectionSnapshot::class,'instance_id')->latestOfMany('inspected_at'); } }
